    mullP(CL, FP, 0, 150, 2.6, 1.15, 0.15, 0.5);
    bandsP(CL, FP, 14, 150, 4.6, 0.9, 0.55);
    prismP(CLd, offP(FP, 0.7), 0, 13.5, true, true); edgeP(CL, FP, 148.5, 1.0, 1.5, 0.8);
    // the corner piers of the shaft run up as pilasters
    for (let i = 0; i < FP.length; i++){ const a = FP[i], b = FP[(i+1) % FP.length]; if (Math.hypot(b[0]-a[0], b[1]-a[1]) > 4) continue; const n = outN(FP, i); wallQ(CL, a, b, 0, 151, n, 0.8); }
    // the stepped tiers
    const tops = [150, 177, 192, 206, 221, 240];
    for (let k = 0; k < PT.length; k++){ const P = revIfCW(PT[k].r), y0 = tops[k], y1 = tops[k + 1];
      prismP(TSL, P, y0, y1, false, true); mullP(TIER, P, y0, y1 - 1.2, 2.2, 0.9, 0.12, 0.55); edgeP(TIER, P, y1 - 1.6, 1.0, 1.6, 0.5);
      prismP(TIER, P, y1 - 0.2, y1); }
    // the antenna mast and its aviation lights
    LCyl(g, 0.5, 1.4, 32, 0.6, 240, 0.6, '#c8ccd0', 8); avLight(B, 0.6, 271.5, 0.6, 1.0);
    for (const y of [222, 241]) for (const p of [[-3, -3], [3, 3]]) avLight(B, p[0] + 0.6, y, p[1] + 0.6, 0.8);
