      const a = P[i], b = P[(i+1) % P.length], n = outN(P, i), m = [(a[0]+b[0])/2 + n[0]*0.6, (a[1]+b[1])/2 + n[1]*0.6], cy = 163;
      const FACE = B.p({c:'#f4f2ea', glow:'#fff6e0', gk:1.1}), RIM = B.p('#3a3f46'), HAND = B.p('#22262b'), ux = -n[1], uz = n[0];
